/*
 * A127248  Triangle whose k-th column is generated by (1-A010060(1+k)*x)*x^k.
 * https://oeis.org/A127248
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, sign, tabl
 * Formula:   a(n) = 1 if n = T(r)+r (r = ⌊(√(8n+1)-1)/2⌋); a(n) =
 *            -popcount(r) mod 2 if n = T(r)+r-1; else a(n) = 0. Here T(r) =
 *            r*(r+1)/2. popcount(r) is the number of 1‑bits in r
 * Range:     i8 n <= 90, i16 n <= 90, i32 n <= 90, i64 n <= 90, i128 n <= 90,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Determine r such that T(r) = r*(r+1)/2 <= n < T(r+1). */
    idx_t r = 0;
    while ((r + 1) * (r + 2) / 2 <= n) {
        ++r;
    }
    idx_t t = r * (r + 1) / 2;
    idx_t c = n - t;          /* column index in row r */

    if (c == r) {
        return 1;             /* the leading 1 in each column */
    } else if (c == r - 1 && r > 0) {
        /* -A010060(r) = -(popcount(r) mod 2) */
        seq_t pop = (__builtin_popcountll(r)) & 1;
        return -(seq_t)pop;
    } else {
        return 0;
    }
}
